53		root := reviewBundleCLIFixture(t)
54		store := posemodel.Store{Root: root}
55		checkpoint := filepath.Join(root, ".pose/closeout-plans/spec-bundle.json")
56		for _, resume := range []string{"`pose close spec:bundle --resume`"} {
57			mustWrite(t, checkpoint, `{"schema_version":1,"scope":"spec:bundle","started_at":"2026-11-08T00:00:00Z","plan_digest":"sha256:old","completed":["context"],"last_error":"verify: unknown"}`)
58			result := posemodel.NewOperationResult("close.apply", "spec:bundle")
59			out := stopOnUnstableInputs(store, "spec:bundle", resume, &result, posemodel.CloseoutStepVerify, "governance read view is unknown")
60			if out.Outcome != posemodel.OutcomeBlocked || out.Error == nil || out.Error.Cause != "terminal-verification-unstable-inputs" || !out.Resumable {
61				t.Fatalf("the stop was not reported as one on unstable inputs: %+v", out)
62			}
63			if !strings.Contains(out.NextAction, "no checkpoint is kept for this stop") || !strings.Contains(out.NextAction, resume) {
64				t.Fatalf("the result does not say where the state is: %q", out.NextAction)
65			}
66			if _, err := os.Stat(checkpoint); err == nil {
67				t.Fatal("a checkpoint of the stop was kept")
68			}
69		}
70	}
